using System;using System.Linq;using UnityEngine;using UnityEngine.UI;using Mirror;using ROM.Progression;using ROM.UI.Gameplay;using W=ROM.UI.Sprint01.RiftWidgets;
namespace ROM.UI.Sprint01 {
public sealed partial class RiftVillageUI {
 bool repairView;
 void RenderRepair(){if(vendorWindow)Destroy(vendorWindow.gameObject);if(vendorBag)Destroy(vendorBag.gameObject);vendorBag=null;var state=RiftJournalView.Read();vendorWindow=ShopPanel("NPC repair",false,650,610);W.Label(vendorWindow,TalkingTo.DisplayName+" · REPARACIÓN",20,20,570,35,23,RiftModernWidgets.Text);ShopButton(vendorWindow,"×",596,18,36,34,Close);W.Label(vendorWindow,"Presupuesto visible · no se cobra por equipo completo",20,67,610,34,15,W.Muted);
 RepairCard(state,"starter:axe","Hacha inicial",state.StarterDurabilityNow,state.StarterDurabilityMax,0);int index=1;foreach(var item in state.LootAxes.Take(RiftJournalPlayer.MaximumLootAxes))RepairCard(state,item.Id,item.RarityLabel+" · Hacha Nv. "+item.Level,item.DurabilityNow,item.DurabilityMax,index++);
 var all=state.RepairQuote("",true);W.Label(vendorWindow,"ORO: "+RiftExplorationProgress.Gold,20,515,300,31,19,new Color(.95f,.77f,.35f));W.Label(vendorWindow,(all?.Missing??0)+" puntos por reparar",320,515,310,31,15,W.Muted);ShopButton(vendorWindow,"VOLVER A COMPRAR",20,559,200,36,()=>{repairView=false;RenderVendor();});var button=ShopButton(vendorWindow,"REPARAR TODO · "+(all?.Cost??0)+" ORO",236,559,394,36,()=>RepairSend("",true,all.Cost));button.interactable=NetworkServer.active&&RiftVendorClient.Current!=null&&all!=null&&all.Missing>0&&ShopPlayer&&!ShopPlayer.Trading;
 var session=RiftVendorClient.Current;if(session!=null&&!string.IsNullOrEmpty(session.Notice))W.Label(vendorWindow,session.Notice,20,472,610,36,14,W.Muted);
 }
 void RepairCard(JournalState state,string id,string name,int durability,int maximum,int index){var quote=state.RepairQuote(id,false);float x=20+(index%2)*308,y=120+(index/2)*84;var button=ShopButton(vendorWindow,"Reparar "+id,x,y,298,76,()=>RepairSend(id,false,quote.Cost));button.GetComponentInChildren<Text>().text="";ItemIcon(button.transform,RiftLootTuning.Load.Item("nertor-axe"),0,6,7,54);W.Label(button.transform,name,70,5,220,26,14,RiftModernWidgets.Text);W.Label(button.transform,durability+" / "+maximum,70,29,220,22,13,W.Muted);W.Label(button.transform,quote!=null&&quote.Missing>0?"Reparar · "+quote.Cost+" oro":"Completa",70,50,220,22,13,new Color(.95f,.77f,.35f));button.interactable=NetworkServer.active&&RiftVendorClient.Current!=null&&quote!=null&&quote.Missing>0&&ShopPlayer&&!ShopPlayer.Trading;var tip=button.gameObject.AddComponent<RiftVendorTooltip>();tip.Title=name;tip.NameColor=id=="starter:axe"?RiftLootLabels.CommonColor:state.LootAxes.FirstOrDefault(x=>x.Id==id)?.DisplayColor;tip.Body="Durabilidad: "+durability+" / "+maximum+"\nCoste de reparación: "+(quote?.Cost??0)+" oro común\nLa reparación conserva nivel, rareza y poder del objeto.";}
 void RepairSend(string id,bool all,int cost){var session=RiftVendorClient.Current;if(session==null||session.Npc!=selectedNpcId||!ShopPlayer)return;ShopPlayer.CmdVendorRepair(session.Token,session.Sequence,id,all,cost);}
}
